const box=document.createElement('div');box.className='fao-view-control';box.innerHTML='<label for="fao-season-view" id="fao-view-label"></label><select id="fao-season-view"><option value="gs1"></option><option value="gs2"></option><option value="municipal"></option></select><p id="fao-view-note" class="map-side-help"></p>';document.getElementById('map-theme').after(box);
