function legend(){document.querySelector('.map-legend-card').classList.add('fao-legend');document.getElementById('map-legend-title').textContent=tr('Frequência histórica de seca (%)','Historical drought frequency (%)')+' · '+(mode==='municipal'?tr('município','municipal'):mode.toUpperCase());const names=['<5','5–<10','10–<15','15–<20','20–<25','25–<30','≥30'];document.getElementById('map-legend-items').innerHTML=names.map((t,i)=>'<span class="herd-map-range"><span class="dot" style="background:rgb('+colors[i].join(',')+')"></span>'+esc(t)+'%</span>').join('')+'<span class="herd-map-range"><span class="dot" style="background:#666"></span>'+tr('Sem estação','No season')+'</span><span class="herd-map-range"><span class="dot" style="background:#ccc"></span>'+tr('Fora da pastagem FAO','Outside FAO grassland')+'</span>'+'<span class="herd-map-range"><span class="dot" style="background:#000"></span>'+tr('Sem dado','No data')+'</span>'+'<span class="herd-map-note">'+tr('FAO ASIS · 1984–2025. ','FAO ASIS · 1984–2025. ')+(mode==='municipal'?tr('Média municipal do máximo de GS1/GS2 por pixel.','Municipal mean of the pixelwise GS1/GS2 maximum.'):tr('Frequência original por pixel, sem média municipal.','Original pixel frequency, without municipal averaging.'))+'</span>';}
function band(v){return Math.min(6,Math.floor(v/5));}
function rgba(v){if(v<=100)return[...colors[band(v)],255];if(v===252)return[0,0,0,255];if(v===253)return[102,102,102,255];if(v===254)return[204,204,204,255];return[0,0,0,0];}
async function values(season){if(cache.has(season))return cache.get(season);const info=data[season],bytes=Uint8Array.from(atob(info.gzip),c=>c.charCodeAt(0));if(!window.DecompressionStream)throw Error('native decoder unavailable');const array=new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer());if(array.length!==info.width*info.height)throw Error('raster size mismatch');cache.set(season,array);return array;}
const NativeGrid=L.GridLayer.extend({initialize:function(info,array){this.info=info;this.array=array;L.GridLayer.prototype.initialize.call(this,{pane:'atlas-fao-pane',tileSize:256,opacity:1,updateWhenIdle:true,keepBuffer:1,zIndex:250});},createTile:function(coords){const canvas=document.createElement('canvas');canvas.width=canvas.height=256;canvas.setAttribute('aria-hidden','true');const x=canvas.getContext('2d'),im=x.createImageData(256,256),s=this.info,world=256*Math.pow(2,coords.z),circ=40075016.68557849;const columns=new Int32Array(256);for(let i=0;i<256;i++)columns[i]=Math.floor((circ*((coords.x*256+i+.5)/world-.5)-s.left)/s.dx);for(let y=0;y<256;y++){const row=Math.floor((s.top-circ*(.5-(coords.y*256+y+.5)/world))/s.dy);if(row<0||row>=s.height)continue;for(let i=0;i<256;i++){const col=columns[i];if(col<0||col>=s.width)continue;const color=rgba(this.array[row*s.width+col]),pos=4*(y*256+i);im.data[pos]=color[0];im.data[pos+1]=color[1];im.data[pos+2]=color[2];im.data[pos+3]=color[3];}}x.putImageData(im,0,0);return canvas;}});
async function activate(){const serial=++request,shown=config.theme()==='4';box.hidden=!shown;if(!shown)document.querySelector('.map-legend-card').classList.remove('fao-legend');if(activeLayer){map.removeLayer(activeLayer);activeLayer=null;}config.raster(shown&&mode!=='municipal');if(!shown)return;legend();if(mode==='municipal')return;try{const s=data[mode],array=await values(mode);if(serial!==request||config.theme()!=='4')return;activeLayer=new NativeGrid(s,array).addTo(map);window.ATLAS_FAO_VIEW=mode;}catch(error){if(serial!==request)return;const s=data[mode];activeLayer=L.imageOverlay(s.fallback,s.bounds,{pane:'atlas-fao-pane',opacity:1,interactive:false,className:'fao-original-raster'}).addTo(map);window.ATLAS_FAO_VIEW=mode;}}
function pixel(latlng){if(mode==='municipal'||!cache.has(mode))return null;const p=map.options.crs.project(latlng),s=data[mode],col=Math.floor((p.x-s.left)/s.dx),row=Math.floor((s.top-p.y)/s.dy);if(row<0||col<0||row>=s.height||col>=s.width)return null;const value=cache.get(mode)[row*s.width+col];return value===255?null:{value,season:mode,row,col};}
map.on('click',e=>{if(config.theme()!=='4'||mode==='municipal')return;const v=pixel(e.latlng);if(!v)return;const message=v.value<=100?fmt(v.value,0)+'%':v.value===253?tr('Sem estação','No season'):v.value===254?tr('Fora da pastagem FAO','Outside FAO grassland'):tr('Sem dado','No data');const content='<strong>FAO '+v.season.toUpperCase()+' · '+esc(message)+'</strong><br>'+tr('Valor do pixel selecionado','Value at the selected pixel');L.popup({maxWidth:250}).setLatLng(e.latlng).setContent(content).openOn(map);window.ATLAS_FAO_LAST_PIXEL=v;});
