const originalLanguage=setLanguage;setLanguage=function(...args){const out=originalLanguage(...args);text();return out;};
LAB_BANDS.green=data.bands[0];LAB_BANDS.orange=data.bands[3];LAB_BANDS.red=data.bands[6];config.colors({green:hex(colors[0]),orange:hex(colors[3]),red:hex(colors[6])},[hex(colors[6]),hex(colors[4]),hex(colors[2]),hex(colors[1]),hex(colors[0])]);function hex(rgb){return'#'+rgb.map(x=>x.toString(16).padStart(2,'0')).join('');}
text();activate();window.ATLAS_FAO_DISPLAY_READY=true;
